import { Component, Prop, Watch, Vue } from 'vue-property-decorator';
import NicknameInput from './components/input-box/index.vue';
import { NicknameServer } from './services/nickname-server';
import NicknameRequirements from './components/requirements/index.vue';
import { NicknameState } from './services/state';
import { INicknameConfig, INicknameState } from './types';
import { Validator } from './services/validator';
import SubmitButton from './components/submit-button/index.vue';
import ErrorInformation from './components/error-information/index.vue';
import { OverlaysEventEmitter } from '../../event-emitter';
import { OPTIONS } from '../../options';
import { INicknameTranslations, IOverlaysPluginOptions } from '../../types';

@Component({
    components: {
        NicknameRequirements,
        NicknameInput,
        SubmitButton,
        ErrorInformation
    }
})
export default class NicknameOverlay extends Vue {
    @Prop()
    protected config: INicknameConfig;

    @Prop()
    protected translations: INicknameTranslations;

    @Watch('state.nickname')
    onNicknameChanged(val: string): void {
        this.validator.validate(val);
    }

    @Watch('state.nicknameAccepted')
    onNicknameAccepted(val: boolean): void {
        if (val === true) {
            const message = this.translations.toast.replace('{nickname}', this.state.nickname);
            OverlaysEventEmitter.emit('showToast', '', message);
            // emitting the nickname incase the game wants to use it.
            OverlaysEventEmitter.emit('nicknameSet', this.state.nickname);
            window.setTimeout(() => {
                this.state.config.isVisible = false;
            }, 500);
        }
    }

    protected options: IOverlaysPluginOptions = OPTIONS;

    protected state: INicknameState;
    protected validator: Validator;
    private nicknameServer: NicknameServer;

    constructor() {
        super();
        this.state = new NicknameState(this.config);
    }

    protected created(): void {
        this.validator = new Validator(this.state);
        this.nicknameServer = new NicknameServer(this.state);
        this.setStartingCharacterTranslation();
        this.setLengthTranslation();
    }

    protected onSubmitNickname(): void {
        this.nicknameServer.submitNickname();
    }

    private setStartingCharacterTranslation(): void {
        this.translations.requirements.startingCharacter =
            this.translations.requirements.startingCharacter.replace('{cMIdentifier}', this.state.config.cMIdentifier);
    }

    private setLengthTranslation(): void {
        let length = this.translations.requirements.length;
        length = length.replace('{minCharacters}', this.state.config.minCharacters.toString());
        length = length.replace('{maxCharacters}', this.state.config.maxCharacters.toString());

        this.translations.requirements.length = length;
    }
}
